---@class BeginnerAssembleTagLinkDialog
local BeginnerAssembleTagLinkDialog = Class('BeginnerAssembleTagLinkDialog')
local ItemCell = "BeginnerAssembleTagLinkListCell"
local JumpNodeCell = "Game.Activity.BeginnerAssemble.Cell.BeginnerAssembleTagLinkListCell"


function BeginnerAssembleTagLinkDialog:__init()

end

function BeginnerAssembleTagLinkDialog:__delete()

end

function BeginnerAssembleTagLinkDialog:Awake()
	self.allVos = CfUtils.GetCf(AutoIds.IdSetting8922,"BeginnerJumpVo",true)
end

function BeginnerAssembleTagLinkDialog:Refresh(config)
	self.config = config
	self:RefreshListShow()
end

function BeginnerAssembleTagLinkDialog:RefreshListShow()
	local count = #self.allVos
	if not self.ScrollView.IsListViewInit then
		self.ScrollView:InitListView(count, Bind(self, self.OnRefreshCellIndex))
	else
		GameUtils.ReloadData(self.ScrollView, count)
	end
end

function BeginnerAssembleTagLinkDialog:OnRefreshCellIndex(listView, index)
	if index < 0 or index >= #self.allVos then
		return
	end
	local cell = listView:NewListViewItem(ItemCell)
	local tableCellEnv = CfUtils.GetLuaScr(cell, JumpNodeCell)
	if tableCellEnv then
		tableCellEnv:SetCallBack(Bind(self,self.OnJumpBtnClick))
		tableCellEnv:RefreshCell(self.allVos[index + 1])
	end
	return cell
end

function BeginnerAssembleTagLinkDialog:OnJumpBtnClick(openType)
	if checkNumber(openType) > 0 then
		local goodsConfMgr = GoodsConfMgr:GetInstance()
		local row = goodsConfMgr:GetJumpModuleRow(openType)
		if row then
			goodsConfMgr:ExecuteJump(row, {},nil,false)
		end
	end
end

function BeginnerAssembleTagLinkDialog:RefreshTopGoods()
	CfUtils.RefreshTopGoods({})
end

function BeginnerAssembleTagLinkDialog:OnDestroy()
	self.controller = nil--luabehaviour 中CSharp对象
	self:Delete()
end

return BeginnerAssembleTagLinkDialog